// Validates the request, mints its id and builds everything the later nodes need.
// Config lives here so there is a single place to edit.
const SUPABASE_URL = '';      // TODO: https://<project>.supabase.co
const DEFAULT_CHAT_ID = '';   // TODO: fallback ops chat, used when the caller omits chat_id
const DEFAULT_TIMEOUT_HOURS = 24;
const MAX_BODY = 3000;        // Telegram rejects messages over ~4096 characters

const input = $input.first().json || {};

const title = String(input.title || '').trim();
if (!title) throw new Error('title is required');

const body = String(input.body || '').trim();
if (!body) throw new Error('body is required');

const chatId = String(input.chat_id || DEFAULT_CHAT_ID).trim();
if (!chatId) throw new Error('chat_id is required and no default is configured');

if (!SUPABASE_URL) throw new Error('SUPABASE_URL is not configured in "Prepare request"');

const timeoutHours = input.timeout_hours === undefined ? DEFAULT_TIMEOUT_HOURS : Number(input.timeout_hours);
if (!Number.isFinite(timeoutHours) || timeoutHours <= 0 || timeoutHours > 168) {
  throw new Error('timeout_hours must be a number between 0 and 168');
}

const source = String(input.source || 'unknown').trim();

// The message is plain text: the draft is arbitrary content and HTML parsing would
// make an unbalanced tag in a draft break delivery of the very thing under review.
const truncated = body.length > MAX_BODY;
const message = title + '\n\n' + (truncated ? body.slice(0, MAX_BODY) + '\n\n[truncated]' : body);

const base = SUPABASE_URL.replace(/\/+$/, '');
const requestId = crypto.randomUUID();

return [{
  json: {
    requestId,
    source,
    title,
    chatId,
    message,
    truncated,
    timeoutHours,
    insertUrl: base + '/rest/v1/approvals',
    // The decision write is filtered on status=pending, so the first decision wins.
    decisionUrl: base + '/rest/v1/approvals?id=eq.' + requestId + '&status=eq.pending',
    row: {
      id: requestId,
      source,
      title,
      status: 'pending',
      created_at: new Date().toISOString(),
    },
  },
}];

// Turns the resumed execution into a decision. Three outcomes only.
// A timed-out wait resumes without an approval field, which is the expired case.
const state = $('Prepare request').first().json;
const response = $input.first().json || {};
const data = response.data || response;

const approved = data.approved;
const timedOut = approved === undefined || approved === null;

const decision = timedOut ? 'expired' : (approved ? 'approved' : 'rejected');
const decidedAt = new Date().toISOString();

return [{
  json: {
    ...state,
    decision,
    decidedAt,
    timedOut,
    patch: {
      status: decision,
      decided_at: decidedAt,
      timed_out: timedOut,
    },
  },
}];

// Single exit shape for the caller.
const s = $input.first().json;
return [{
  json: {
    request_id: s.requestId,
    decision: s.decision,
    decided_at: s.decidedAt,
    timed_out: s.timedOut,
    title: s.title,
    source: s.source,
  },
}];
